// ---- src/engine/rng.mjs ----
// rng.mjs — seeded multi-stream PRNG (mulberry32 class).
// Separate streams: rng.encounter / rng.battle / rng.misc — QA can lock battle RNG
// while leaving encounters live (architecture §7.1). Same seed + same inputs =
// identical playthrough.

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function makeRngStreams(seed) {
  const s = seed >>> 0;
  return {
    seed: s,
    encounter: mulberry32(s ^ 0x9e3779b9),
    battle: mulberry32(s ^ 0x85ebca6b),
    misc: mulberry32(s ^ 0xc2b2ae35),
  };
}

// roll(p, rngFn): true with probability p in [0,1].
function roll(p, rngFn) {
  return rngFn() < p;
}

// intIn(lo, hi, rngFn): uniform integer in [lo, hi].
function intIn(lo, hi, rngFn) {
  return lo + Math.floor(rngFn() * (hi - lo + 1));
}

// pick weighted: entries [[weight, value], ...]
function pickWeighted(entries, rngFn) {
  let total = 0;
  for (let i = 0; i < entries.length; i++) total += entries[i][0];
  let r = rngFn() * total;
  for (let i = 0; i < entries.length; i++) {
    r -= entries[i][0];
    if (r <= 0) return entries[i][1];
  }
  return entries[entries.length - 1][1];
}


// ---- src/engine/formulas.mjs ----
// formulas.mjs — battle math as PURE functions (architecture §7.3).
// Reimplemented from documented Gen 4/5 systems (dossier §B). Named exports double
// as the ADR note's documented constants. Unit-testable without a browser.

const TYPES = [
  'normal', 'fire', 'water', 'electric', 'grass', 'ice',
  'fighting', 'poison', 'ground', 'flying', 'psychic', 'bug',
  'rock', 'ghost', 'dragon', 'dark', 'steel', 'fairy',
];

// Attacking type -> defending type -> multiplier. Absent = 1.
const TYPE_CHART = {
  normal:   { rock: 0.5, ghost: 0, steel: 0.5 },
  fire:     { fire: 0.5, water: 0.5, grass: 2, ice: 2, bug: 2, rock: 0.5, dragon: 0.5, steel: 2 },
  water:    { fire: 2, water: 0.5, grass: 0.5, ground: 2, rock: 2, dragon: 0.5 },
  electric: { water: 2, electric: 0.5, grass: 0.5, ground: 0, flying: 2, dragon: 0.5 },
  grass:    { fire: 0.5, water: 2, grass: 0.5, poison: 0.5, ground: 2, flying: 0.5, bug: 0.5, rock: 2, dragon: 0.5, steel: 0.5 },
  ice:      { fire: 0.5, water: 0.5, grass: 2, ice: 0.5, ground: 2, flying: 2, dragon: 2, steel: 0.5 },
  fighting: { normal: 2, ice: 2, poison: 0.5, flying: 0.5, psychic: 0.5, bug: 0.5, rock: 2, ghost: 0, dark: 2, steel: 2, fairy: 0.5 },
  poison:   { grass: 2, poison: 0.5, ground: 0.5, rock: 0.5, ghost: 0.5, steel: 0, fairy: 2 },
  ground:   { fire: 2, electric: 2, grass: 0.5, poison: 2, flying: 0, bug: 0.5, rock: 2, steel: 2 },
  flying:   { electric: 0.5, grass: 2, fighting: 2, bug: 2, rock: 0.5, steel: 0.5 },
  psychic:  { fighting: 2, poison: 2, psychic: 0.5, dark: 0, steel: 0.5 },
  bug:      { fire: 0.5, grass: 2, fighting: 0.5, poison: 0.5, flying: 0.5, psychic: 2, ghost: 0.5, dark: 2, steel: 0.5, fairy: 0.5 },
  rock:     { fire: 2, ice: 2, fighting: 0.5, ground: 0.5, flying: 2, bug: 2, steel: 0.5 },
  ghost:    { normal: 0, psychic: 2, ghost: 2, dark: 0.5 },
  dragon:   { dragon: 2, steel: 0.5, fairy: 0 },
  dark:     { fighting: 0.5, psychic: 2, ghost: 2, dark: 0.5, fairy: 0.5 },
  steel:    { fire: 0.5, water: 0.5, electric: 0.5, ice: 2, rock: 2, steel: 0.5, fairy: 2 },
  fairy:    { fire: 0.5, fighting: 2, poison: 0.5, dragon: 2, dark: 2, steel: 0.5 },
};

function effectiveness(moveType, defenderTypes) {
  const row = TYPE_CHART[moveType] || {};
  let m = 1;
  for (let i = 0; i < defenderTypes.length; i++) {
    m *= (row[defenderTypes[i]] !== undefined ? row[defenderTypes[i]] : 1);
  }
  return m;
}

// Damage: classic formula floor(floor(floor(2*L/5+2)*Power*A/D)/50)+2 with
// Generation-I critical-hit semantics (ADR-018): on a crit the LEVEL is
// doubled inside the formula (no separate 2x multiplier), the attacker's
// negative and defender's positive stat stages are ignored (the caller
// passes raw stats), and burn does not halve. Random factor is the classic
// integer roll 217-255 / 255 (see gen1Random). STAB 1.5x. Type chart is the
// complete modern 18-type chart per the WS8 ruling (ADR-018): fidelity
// governs feel, pacing and presentation in Kanto — not chart bugs.
function calcDamage(level, power, atk, def, opts) {
  const o = opts || {};
  const stab = o.stab ? 1.5 : 1;
  const eff = o.effectiveness !== undefined ? o.effectiveness : 1;
  const rand = o.random !== undefined ? o.random : 1;
  const effLevel = o.crit ? level * 2 : level;
  // Gen 1: burn halves the physical Attack STAT before the formula (and a
  // critical hit ignores the halving, like it ignores stat stages).
  const a = (o.burn && o.physical && !o.crit) ? Math.floor(atk / 2) : atk;
  const base = Math.floor(Math.floor(Math.floor((2 * effLevel) / 5 + 2) * power * a / def) / 50) + 2;
  // Rejuvenation Phase 2 (ADR-025 §1): the Ground factor — the ONE place
  // it applies, inside the shared damage path both engines call. The
  // field (battle.field, resolved at battle start, Story halving already
  // folded in) supplies effective boost/dampen factors for the move's
  // type; hard caps x1.2 / x0.8 live in the Grounds data. Typeless calls
  // (confusion self-hit: no field / no moveType passed) are untouched.
  let gf = 1;
  const f = o.field;
  if (f && o.moveType) {
    if (f.boostType && o.moveType === f.boostType) gf = f.boostFactor !== undefined ? f.boostFactor : 1.2;
    else if (f.dampenType && o.moveType === f.dampenType) gf = f.dampenFactor !== undefined ? f.dampenFactor : 0.8;
  }
  if (o.groundFactor !== undefined) gf = o.groundFactor;
  // Rejuvenation Phase 3 (ADR-025 §3): the Keepsake factor — resolved by
  // src/game/keepsakes.mjs (both attacker- and defender-side windows)
  // and applied here ONCE, AFTER the Ground factor, in the same shared
  // path. Absent = 1 (typeless/fixed-damage calls are untouched, as
  // with the Ground factor).
  const kf = o.keepsakeFactor !== undefined ? o.keepsakeFactor : 1;
  return Math.max(1, Math.floor(base * stab * eff * rand * gf * kf));
}

function gen1Random(rng) { return (217 + Math.floor(rng() * 39)) / 255; }

// Generation-I critical-hit rate, exact form: normal T = base Speed,
// P = T/512; high-crit moves (Slash, Razor Leaf, Karate Chop, Crabhammer)
// T = min(255, base Speed x 4), P = T/256. Focus Energy multiplies the rate
// by 4 (the original divided by 4 — a bug; not reproduced, ADR-018 D4).
function critChance(baseSpeed, opts) {
  const o = opts || {};
  let c = o.highCrit ? Math.min(255, baseSpeed * 4) / 256 : baseSpeed / 512;
  if (o.focus) c *= 4;
  // Grounds (ADR-025 §1, Tide classic twist): an additive bonus the caller
  // computes from the field (special moves: + base Speed/256).
  if (o.bonus) c += o.bonus;
  return Math.min(1, c);
}
const STAB_MULT = 1.5;

// Stat stage ladder: stage in [-6, 6]; each stage x1.5 / ÷1.5.
function stageMultiplier(stage) {
  if (stage >= 0) return (2 + stage) / 2;
  return 2 / (2 - stage);
}

// Accuracy/evasion stage ladder (classic table): (3+s)/3 up, 3/(3-s) down.
function accStageMultiplier(stage) {
  if (stage >= 0) return (3 + stage) / 3;
  return 3 / (3 - stage);
}

function statValue(base, level, iv) {
  const v = iv === undefined ? 31 : iv;
  return Math.floor(((2 * base + v) * level) / 100) + 5;
}
function hpValue(base, level, iv) {
  const v = iv === undefined ? 31 : iv;
  return Math.floor(((2 * base + v) * level) / 100) + level + 10;
}

// Catch: Generation-I two-roll system (ADR-018). Roll R uniformly in the
// ball's range (poke 0-255, great 0-200, ultra 0-150, master = automatic).
// Status shifts R down (sleep/freeze -25, poison/burn/paralysis -12).
// R < 0 => caught; R > catchRate => immediate fail; otherwise the HP factor
// f = (HPmax * 255 * 4) / (HPcur * divisor) (divisor 8 for Great Ball, else
// 12, f capped at 255) and a second roll R2 in 0-255 catches iff R2 <= f.
// Wobble count for animation comes from how far R fell under the rate.
const BALL_RANGES = { pokeball: 255, greatball: 200, ultraball: 150, masterball: 0, safariball: 255 };
function gen1Catch(hpMax, hpCur, catchRate, ballId, status, rng) {
  if (ballId === 'masterball') return { caught: true, shakes: 3 };
  const range = BALL_RANGES[ballId] !== undefined ? BALL_RANGES[ballId] : 255;
  let r = Math.floor(rng() * (range + 1));
  if (status === 'sleep' || status === 'freeze') r -= 25;
  else if (status === 'poison' || status === 'burn' || status === 'paralysis' || status === 'badlyPoisoned') r -= 12;
  if (r < 0) return { caught: true, shakes: 3 };
  if (r > catchRate) return { caught: false, shakes: 0 };
  const divisor = ballId === 'greatball' ? 8 : 12;
  let f = Math.floor((hpMax * 255 * 4) / (Math.max(1, hpCur) * divisor));
  if (f > 255) f = 255;
  const r2 = Math.floor(rng() * 256);
  if (r2 <= f) return { caught: true, shakes: 3 };
  const shakes = r < catchRate / 3 ? 1 : (r < (2 * catchRate) / 3 ? 2 : 2);
  return { caught: false, shakes };
}

// XP: documented growth curves reimplemented (GD §3.4).
function xpForLevel(curve, level) {
  const n = level;
  switch (curve) {
    case 'erratic':
      if (n <= 50) return Math.floor((n * n * n * (100 - n)) / 50);
      if (n <= 68) return Math.floor((n * n * n * (150 - n)) / 100);
      if (n <= 98) return Math.floor((n * n * n * ((1911 - 10 * n) / 3)) / 500);
      return Math.floor((n * n * n * (160 - n)) / 100);
    case 'fast': return Math.floor((4 * n * n * n) / 5);
    case 'mediumfast': return n * n * n;
    case 'mediumslow': return Math.floor((6 / 5) * n * n * n - 15 * n * n + 100 * n - 140);
    case 'slow': return Math.floor((5 * n * n * n) / 4);
    case 'fluctuating':
      if (n <= 15) return Math.floor((n * n * n * (((n + 1) / 3 + 24) / 50)));
      if (n <= 36) return Math.floor((n * n * n * ((n + 14) / 50)));
      return Math.floor((n * n * n * ((n / 2 + 32) / 50)));
    default: return n * n * n;
  }
}

// Save-validation XP ceiling for a level cap (ADR-027 Amendment 2,
// Stage J0): the most XP a mon can legitimately hold at that cap.
// The slowest growth curve among the game's species is 'slow' (the
// shipped species census uses fast / mediumfast / mediumslow / slow
// only — erratic and fluctuating have no species), so the ceiling is
// read off xpForLevel('slow', cap + 1): a mon AT the cap earned its
// last level against that threshold and its final XP share (or an XP
// Candy) can carry it past xpForLevel('slow', cap). The x2 slack is
// the generous margin for post-cap accumulation — the battle XP loop
// keeps adding shares to a capped mon without levelling it. An
// open-level cap (Infinity — the Battle Frontier) has no ceiling.
// The client schema, the server validator (via the gen-tables
// emission) and this function are the matched pair: one derivation,
// never a hand-copied number.
const XP_CEILING_SLACK = 2;
function xpCeilingForCap(cap) {
  if (typeof cap !== 'number' || !Number.isFinite(cap)) return Infinity;
  return XP_CEILING_SLACK * xpForLevel('slow', cap + 1);
}

// Simplified documented-style XP yield: base * level / 7; trainer battles pay
// the documented Gen 5-era 1.5x (GD balance: the slice's XP economy runs on
// trainer payouts, not wild grinding).
function xpYield(baseXp, level, isWild) {
  return Math.max(1, Math.floor((baseXp * level) / 7 * (isWild ? 1 : 1.5)));
}

// Turn order: priority bracket -> Speed (paralysis quarters Speed, Gen 4-6) -> random.
function turnOrder(a, b, rng) {
  const pa = a.priority || 0, pb = b.priority || 0;
  if (pa !== pb) return pa > pb ? [a, b] : [b, a];
  const sa = a.status === 'paralysis' ? Math.floor(a.speed / 4) : a.speed;
  const sb = b.status === 'paralysis' ? Math.floor(b.speed / 4) : b.speed;
  if (sa !== sb) return sa > sb ? [a, b] : [b, a];
  return rng() < 0.5 ? [a, b] : [b, a];
}


// ---- src/engine/loop.mjs ----
// loop.mjs — fixed-timestep 30 Hz sim + interpolated rAF render (architecture §2.1).
// Sim tick 30 Hz. Render every rAF with accumulator alpha. Max 5 catch-up steps
// (spiral-of-death guard). Input sampled per rAF, applied at next tick.
// visibilitychange -> sim halts + autosave hook (dossier).

const SIM_HZ = 30;
const SIM_DT = 1 / SIM_HZ;
const MAX_CATCHUP = 5;

class Loop {
  constructor(game) {
    this.game = game;
    this.acc = 0;
    this.last = 0;
    this.running = false;
    this.rafId = 0;
    this.frameTimes = []; // rolling frame-time histogram (perf HUD, QA)
    this.onAutosave = null;
    this._tick = this._tick.bind(this);
  }

  start() {
    if (this.running) return;
    this.running = true;
    this.last = this._now();
    const raf = typeof requestAnimationFrame !== 'undefined'
      ? requestAnimationFrame
      : (cb) => setTimeout(() => cb(this._now()), 16);
    const step = (t) => {
      if (!this.running) return;
      this._tick(t);
      this.rafId = raf(step);
    };
    this.rafId = raf(step);
  }

  stop() {
    this.running = false;
    if (typeof cancelAnimationFrame !== 'undefined') cancelAnimationFrame(this.rafId);
  }

  // Headless / test driver: advance the sim by exactly n ticks.
  stepTicks(n) {
    for (let i = 0; i < n; i++) {
      this.game.update(SIM_DT);
    }
    this.game.render(1);
  }

  // Advance wall-clock ms (for headless time-based sequences like the 3s disclaimer).
  stepMs(ms) {
    let remaining = ms / 1000;
    while (remaining > 0) {
      const dt = Math.min(remaining, SIM_DT);
      this.game.update(dt);
      remaining -= dt;
    }
    this.game.render(1);
  }

  _now() {
    return (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
  }

  _tick(t) {
    let frameMs = t - this.last;
    this.last = t;
    if (frameMs > 250) frameMs = 250; // background-tab return: drop debt
    this.acc += frameMs / 1000;
    let steps = 0;
    while (this.acc >= SIM_DT && steps < MAX_CATCHUP) {
      this.game.input.sample();
      this.game.update(SIM_DT);
      this.acc -= SIM_DT;
      steps++;
    }
    if (steps === MAX_CATCHUP) this.acc = 0; // shed excess debt, never spiral
    const alpha = Math.min(1, this.acc / SIM_DT);
    const t0 = this._now();
    this.game.render(alpha);
    const cost = this._now() - t0;
    this.frameTimes.push(cost);
    if (this.frameTimes.length > 240) this.frameTimes.shift();
  }

  // Mean frame cost over the last window (ms) — QA perf overlay.
  meanFrameCost() {
    if (!this.frameTimes.length) return 0;
    let s = 0;
    for (let i = 0; i < this.frameTimes.length; i++) s += this.frameTimes[i];
    return s / this.frameTimes.length;
  }

  bindVisibility(pauseFn) {
    if (typeof document === 'undefined' || !document.addEventListener) return;
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) {
        if (this.onAutosave) this.onAutosave();
        if (pauseFn) pauseFn();
      }
    });
  }
}


// ---- src/engine/input.mjs ----
// input.mjs — keyboard + touch D-pad/A/B input with per-tick edge detection.
// DOM overlays are built by ui.mjs; this module owns state. Headless driver injects
// via `inject(code)` / `release(code)`. 4-way D-pad: last-pressed-wins diagonals.

const KEYMAP = {
  ArrowUp: 'up', KeyW: 'up',
  ArrowDown: 'down', KeyS: 'down',
  ArrowLeft: 'left', KeyA: 'left',
  ArrowRight: 'right', KeyD: 'right',
  KeyZ: 'a', Space: 'a',
  Enter: 'start', // Uix ruling (phase4-uix-signoff): Enter = START, A = Z/Space. One key, one job.
  KeyX: 'b', Backspace: 'b',
  ShiftLeft: 'select', ShiftRight: 'select',
  KeyQ: 'pageup', KeyE: 'pagedown',
  PageUp: 'pageup', PageDown: 'pagedown', // laptop physicals (Mac: fn+↑/↓)
  Digit1: 'slot1', Digit2: 'slot2', Digit3: 'slot3', Digit4: 'slot4',
  KeyF: 'fullscreen', KeyM: 'mute', Escape: 'escape',
};
const ACTIONS = ['up', 'down', 'left', 'right', 'a', 'b', 'start', 'select',
  'pageup', 'pagedown', 'slot1', 'slot2', 'slot3', 'slot4', 'fullscreen', 'mute', 'escape'];

class Input {
  constructor() {
    this.held = {};      // action -> bool (current physical state)
    this.pressed = {};   // action -> bool (edge: went down since last sample)
    this._dirStack = []; // last-pressed-wins for diagonals
    this.remap = Object.assign({}, KEYMAP);
    this.flipControls = false;
    for (const a of ACTIONS) { this.held[a] = false; this.pressed[a] = false; }
    this._bound = false;
  }

  bindKeyboard() {
    if (this._bound || typeof document === 'undefined') return;
    this._bound = true;
    // AUDIT FIX (S-38, blocker): keystrokes typed into form fields (auth
    // username/password, any DOM input) belong to the field, never to the
    // game — without this shield, letters a/d/s/w/z/x and Space were
    // preventDefault()ed as game keys and could not be typed at all.
    const fromField = (e) => {
      const t = e.target;
      return !!t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' || t.isContentEditable);
    };
    const down = (e) => {
      if (fromField(e)) return;
      const action = this.remap[e.code];
      if (!action) return;
      if (['up', 'down', 'left', 'right', 'a', 'b'].includes(action)) e.preventDefault();
      this._press(action, !!e.repeat);
    };
    const up = (e) => {
      if (fromField(e)) return;
      const action = this.remap[e.code];
      if (!action) return;
      this._release(action);
    };
    document.addEventListener('keydown', down);
    document.addEventListener('keyup', up);
    // Touch overlays call press/release directly.
  }

  _press(action, repeat) {
    // AUDIT FIX (laptop paging): OS key-repeat re-fires direction edges so
    // HOLDING an arrow scrolls menus/lists (Platinum behavior). Buttons
    // (a/b/start) stay edge-only — a held A must never double-confirm.
    if (!this.held[action] || (repeat && ['up', 'down', 'left', 'right'].includes(action))) this.pressed[action] = true;
    this.held[action] = true;
    if (['up', 'down', 'left', 'right'].includes(action)) {
      this._dirStack = this._dirStack.filter((d) => d !== action);
      this._dirStack.push(action);
    }
  }

  _release(action) {
    this.held[action] = false;
    this._dirStack = this._dirStack.filter((d) => d !== action);
  }

  // Public API for touch overlays + headless driver.
  press(action) { this._press(action); }
  release(action) { this._release(action); }
  inject(action) { this._press(action); }      // headless: momentary press
  releaseAll() {
    for (const a of ACTIONS) this._release(a);
  }

  // Called once per sim tick (and per rAF in loop) — edges consumed here.
  sample() {
    // pressed[] stays true until consumed by game code via wasPressed().
  }

  wasPressed(action) {
    const p = !!this.pressed[action];
    this.pressed[action] = false;
    return p;
  }

  isHeld(action) { return !!this.held[action]; }

  // 4-way direction, last-pressed wins (diagonals ignored per gameux §2).
  dir() {
    return this._dirStack.length ? this._dirStack[this._dirStack.length - 1] : null;
  }

  consumeAll() {
    for (const a of ACTIONS) this.pressed[a] = false;
  }
}


// ---- src/engine/audio.mjs ----
// audio.mjs — WebAudio chiptune engine: note-table player with loop scheduler.
// Contract: docs/contracts.md §2. Score lives in audio/note-tables.mjs
// (import stripped by the zero-dep build; module-order.json pins it first).
// 4-6 channel budget (2 pulse, 1 triangle, 1 noise) enforced by VOICE_BUDGET.
// Music unlocks on first user gesture. Safe no-op when AudioContext is
// unavailable (headless / SSR). Persisted mute + volume via applySettings.
// Every gameplay-critical cue keeps a visual twin (see audio/SCORE.md).


const CHANNELS = ['pulse1', 'pulse2', 'triangle', 'noise'];
const VOICE_BUDGET = 6; // hard cap on concurrent live voices (polyphony discipline)
const SFX_SCALE = 0.06; // SFX beats -> seconds (60ms per beat)
const EPS = 1e-6; // sub-audible simultaneity epsilon for voice-overlap math

const PITCH_RE = /^([A-G][#b]?)(\d)$/;
const NAMES = { C: 0, 'C#': 1, D: 2, 'D#': 3, E: 4, F: 5, 'F#': 6, G: 7, 'G#': 8, A: 9, 'A#': 10, Bb: 10, B: 11 };

function freqOf(pitch) {
  // Scientific pitch notation -> Hz. A4 = 440.
  const m = PITCH_RE.exec(pitch);
  if (!m) return 440;
  const midi = ((parseInt(m[2], 10) + 1) * 12) + NAMES[m[1]];
  return 440 * Math.pow(2, (midi - 69) / 12);
}

const MUSIC_TRACKS = MUSIC;
const CRY_TABLE = CRIES;
// Legacy key compatibility for existing call sites: blip/tick/back/fanfare/heal/
// error/throw_/rattle/click/dex/lowhp/encounter all exist in SFXSET.
const SFX = SFXSET;

class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;   // mute switch
    this.musicBus = null; // music volume
    this.sfxBus = null;   // sfx volume
    this.muted = false;
    this.musicVol = 0.8;
    this.sfxVol = 0.8;
    this.reducedMotion = false;
    this._unlocked = false;
    this._musicId = null;      // currently playing music track
    this._areaMusicId = null;  // last non-battle track (restore target)
    this._schedTimer = null;
    this._noiseBuf = null;
    this._pulseWaves = {};
    // Polyphony discipline: track scheduled voices as [start, stop) windows;
    // the cap applies to voices *sounding together*, not to the whole
    // look-ahead queue (a scheduled loop holds dozens of future notes).
    this._live = [];
  }

  // Call from the first user gesture (A press / tap). AC may be injected
  // (tests) — otherwise resolves the browser's AudioContext.
  unlock(AC) {
    if (this._unlocked) return;
    const Ctor = AC || (typeof AudioContext !== 'undefined' ? AudioContext
      : (typeof webkitAudioContext !== 'undefined' ? webkitAudioContext : null));
    if (!Ctor) return; // headless: stay silent, never throw
    try {
      this.ctx = new Ctor();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 1;
      this.musicBus = this.ctx.createGain();
      this.musicBus.gain.value = this.musicVol;
      this.sfxBus = this.ctx.createGain();
      this.sfxBus.gain.value = this.sfxVol;
      this.musicBus.connect(this.master);
      this.sfxBus.connect(this.master);
      this.master.connect(this.ctx.destination);
      this._unlocked = true;
      // If a track was requested before unlock (e.g. title theme queued at
      // boot), start it now that the gesture arrived. _musicId is cleared
      // first so the same-id no-op guard doesn't swallow the replay.
      if (this._pendingMusic) { const id = this._pendingMusic; this._pendingMusic = null; this._musicId = null; this.playMusic(id); }
    } catch (e) { /* audio unavailable: silent mode */ }
  }

  setMuted(m) {
    this.muted = !!m;
    if (this.master && this.ctx) {
      this.master.gain.setValueAtTime(this.muted ? 0 : 1, this.ctx.currentTime);
    }
  }

  setMusicVolume(v) {
    this.musicVol = Math.min(1, Math.max(0, +v || 0));
    if (this.musicBus && this.ctx) {
      this.musicBus.gain.setValueAtTime(this.musicVol, this.ctx.currentTime);
    }
  }

  setSfxVolume(v) {
    this.sfxVol = Math.min(1, Math.max(0, +v || 0));
    if (this.sfxBus && this.ctx) {
      this.sfxBus.gain.setValueAtTime(this.sfxVol, this.ctx.currentTime);
    }
  }

  setReducedMotion(b) {
    this.reducedMotion = !!b;
  }

  // Persisted settings object from game state: { mute, musicVol, sfxVol, reducedMotion }.
  applySettings(s) {
    if (!s) return;
    this.setMuted(!!s.mute);
    if (typeof s.musicVol === 'number') this.setMusicVolume(s.musicVol);
    if (typeof s.sfxVol === 'number') this.setSfxVolume(s.sfxVol);
    this.setReducedMotion(!!s.reducedMotion);
  }

  // ---- music ----
  _tableBeats(table) {
    let end = 0;
    for (const tr of table.tracks || []) {
      for (const [beat, , beats] of tr.notes) end = Math.max(end, beat + beats);
    }
    return end;
  }

  // id: key in MUSIC. opts.area=false for battle music (not a restore target).
  // No-op when the same track is already playing (no restart churn on warps).
  playMusic(id, opts) {
    if (!id || !MUSIC[id]) return;
    const area = !opts || opts.area !== false;
    if (this._musicId === id) { if (area) this._areaMusicId = id; return; }
    this._musicId = id;
    if (area) this._areaMusicId = id;
    if (!this._unlocked || !this.ctx) { this._pendingMusic = id; return; }
    this._clearSched();
    const table = MUSIC[id];
    const spb = 60 / (table.bpm || 120);
    const loopLen = Math.max(0.25, this._tableBeats(table) * spb);
    let nextStart = this.ctx.currentTime + 0.06;
    const scheduleLoop = () => {
      const t0 = nextStart;
      try {
        for (const tr of table.tracks) {
          for (const [beat, pitch, beats] of tr.notes) {
            this._schedule(tr, pitch, t0 + beat * spb, beats * spb, tr.vol || 0.5, this.musicBus);
          }
        }
      } catch (e) { /* never let audio break the game */ }
      nextStart = t0 + loopLen;
      this._schedTimer = setTimeout(scheduleLoop, Math.max(0, (nextStart - this.ctx.currentTime - 0.25) * 1000));
    };
    scheduleLoop();
  }

  stopMusic() {
    this._clearSched();
    this._musicId = null;
  }

  restoreAreaMusic() {
    if (this._areaMusicId) this.playMusic(this._areaMusicId);
  }

  _clearSched() {
    if (this._schedTimer) { clearTimeout(this._schedTimer); this._schedTimer = null; }
  }

  // ---- SFX ----
  // key: SFXSET key (e.g. 'ui-blip') or a raw table { wave, duty, vol, env, notes }.
  playSfx(key) {
    if (!this._unlocked || !this.ctx || this.muted) return;
    const table = typeof key === 'string' ? SFXSET[key] : key;
    if (!table) return;
    const t = this.ctx.currentTime;
    const tr = table.track || table;
    try {
      for (const [beat, pitch, beats] of (tr.notes || [])) {
        this._schedule(
          { wave: tr.wave || 'pulse', duty: tr.duty || 0.5, env: tr.env },
          pitch, t + beat * SFX_SCALE, beats * SFX_SCALE, tr.vol || 0.5, this.sfxBus,
        );
      }
    } catch (e) { /* never let audio break the game */ }
  }

  // Convenience pairs (visual twins live in the scenes; see audio/SCORE.md).
  encounter() { this.playSfx('encounter-sting'); this.playSfx('encounter-sting-melody'); }
  transition() { this.playSfx(this.reducedMotion ? 'transition-fade' : 'transition-whoosh'); }
  playCry(speciesId) {
    const cry = CRIES[speciesId];
    this.playSfx(cry || { wave: 'pulse', duty: 0.25, vol: 0.35, env: [0.004, 0.15], notes: [[0, 'E5', 1], [1, 'C5', 1]] });
  }
  // Battle impact theater: sound picks the effectiveness tier.
  hitFeedback(eff) {
    if (eff > 1) { this.playSfx('battle-super-boom'); this.playSfx('battle-super'); }
    else if (eff < 1) { this.playSfx('battle-hit'); this.playSfx('battle-noteff'); }
    else { this.playSfx('battle-hit'); this.playSfx('battle-hit-tone'); }
  }
  catchBreakout() { this.playSfx('catch-breakout'); this.playSfx('catch-breakout-tone'); }

  // ---- voice synthesis ----
  _schedule(tr, pitch, t, dur, vol, bus) {
    if (!this.ctx || !bus) return;
    if (!this._voiceSlot(t, dur)) return; // polyphony discipline: 4-6 channels
    const g = this.ctx.createGain();
    const env = tr.env; // [attack, decay] seconds; peak = vol
    try {
      if (tr.wave === 'noise') {
        const src = this.ctx.createBufferSource();
        src.buffer = this._noiseBuffer();
        const f = this.ctx.createBiquadFilter();
        f.type = 'highpass'; f.frequency.value = 1000;
        this._applyEnv(g.gain, t, vol, dur, env);
        src.connect(f); f.connect(g); g.connect(bus);
        this._voiceStart(src, t, Math.max(dur, env ? env[0] + env[1] : dur));
      } else {
        const o = this.ctx.createOscillator();
        if (tr.wave === 'triangle') { o.type = 'triangle'; }
        else { o.setPeriodicWave(this._pulseWave(tr.duty || 0.5)); }
        if (pitch) o.frequency.value = freqOf(pitch);
        this._applyEnv(g.gain, t, vol, dur, env);
        o.connect(g); g.connect(bus);
        this._voiceStart(o, t, Math.max(dur, env ? env[0] + env[1] : dur));
      }
    } catch (e) { /* never let audio break the game */ }
  }

  _applyEnv(param, t, vol, dur, env) {
    if (env && env.length === 2) {
      param.setValueAtTime(0.0001, t);
      param.linearRampToValueAtTime(Math.max(0.0001, vol), t + env[0]);
      param.exponentialRampToValueAtTime(0.0001, t + env[0] + env[1]);
    } else {
      param.setValueAtTime(vol, t);
      param.exponentialRampToValueAtTime(0.0001, t + dur);
    }
  }

  // True when a new voice [t, t+dur) can start without exceeding the budget.
  // Measures *simultaneous* voices: the sweep checks every instant where the
  // overlap count can change (the new note's start + each existing note's
  // start inside its span) — the same event-sweep the verify-audio audit uses.
  // EPS: note times are absolute AudioContext seconds (large magnitudes), so
  // float association noise can leave a 1-ulp phantom "overlap" between a
  // voice that just ended and one starting now. 1µs is far below audibility.
  _voiceSlot(t, dur) {
    const now = this.ctx ? this.ctx.currentTime : 0;
    this._live = this._live.filter((v) => v.stop > now);
    const instants = [t];
    for (const v of this._live) if (v.start > t + EPS && v.start < t + dur) instants.push(v.start);
    for (const s of instants) {
      let n = 0;
      for (const v of this._live) if (v.start <= s + EPS && v.stop > s + EPS) n++;
      if (n >= VOICE_BUDGET) return false;
    }
    return true;
  }

  _voiceStart(node, t, stopDur) {
    // Budget window ends at stopDur (the +0.03 below is sub-audible scheduling
    // slack, excluded so the budget audit and the engine agree).
    this._live.push({ start: t, stop: t + stopDur });
    node.onended = () => { /* window-pruned in _voiceSlot; kept for debuggers */ };
    node.start(t);
    node.stop(t + stopDur + 0.03);
  }

  // Duty-cycle pulse timbres (0.125 / 0.25 / 0.5) via PeriodicWave.
  _pulseWave(duty) {
    const key = String(duty);
    if (!this._pulseWaves[key]) {
      const N = 24;
      const real = new Float32Array(N);
      const imag = new Float32Array(N);
      real[0] = 2 * duty - 1;
      for (let k = 1; k < N; k++) {
        imag[k] = (k % 2 === 1) ? (4 / (k * Math.PI)) * Math.sin(k * Math.PI * duty) : 0;
      }
      this._pulseWaves[key] = this.ctx.createPeriodicWave(real, imag, { disableNormalization: true });
    }
    return this._pulseWaves[key];
  }

  _noiseBuffer() {
    if (this._noiseBuf) return this._noiseBuf;
    const len = Math.floor(this.ctx.sampleRate * 0.5);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    this._noiseBuf = buf;
    return buf;
  }
}


// ---- src/engine/render.mjs ----
// render.mjs — Canvas 2D renderer with the ADR-007 perf budgets.
// DPR auto-tier: cap 2; tier to 1 on <=2GB RAM or software rasterizer.
// Viewport culling: only tiles/entities intersecting the camera rect are drawn.
// Hot-path rules: no shadowBlur, no per-frame gradients, imageSmoothingEnabled=false.

const TILE = 16;

// Wave 0 size standard (world-art census §3): battlers are authored at
// 64x64 and drawn at 64 logical px on BOTH sides (foe/ally parity);
// legacy 32x32 art is upscaled x2 (nearest-neighbor) to the same 64.
// One constant, derived everywhere from the art entry's `size` — no
// per-side draw-size literals in the battle engines.
const BATTLER_DRAW_SIZE = 64;

// UI v2 (Platinum standard): the UI typefaces are the self-hosted OFL
// pixel faces — Galmuri (display) and the body face. Canvas text uses
// the same stacks as the shell CSS tokens.
// UI v2.3 (defect 1, SUPERSEDED by v2.4 below): body text moved to
// DotGothic16; Galmuri kept for DISPLAY only (title screen, headings —
// see UI_DISPLAY_FONT_STACK and the --font-display CSS token).
// UI_FONT_STACK is the BODY stack: canvas body
// text (battle messages, databoxes, prompts) draws with it, and wrapText()
// measures with the identical string, so measure and render can never
// diverge again (the v2.2 mid-word clip: 'y/our first catch').
// UI v2.4 (defect 1): the body face is Pixelify Sans ('PtPixel', 400+700).
// DotGothic16's bytes were verified sound (full Latin, loaded, applied)
// but its half-width dot-matrix Latin dissolves into wispy strokes at
// 13–16px in Chromium — see docs/ui-v24-root-cause.md. Pixelify's solid
// filled letterforms hold up at body sizes.
const UI_FONT_STACK = "'PtPixel', 'PtGalmuri', system-ui, -apple-system, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif";
// Display stack (headings / title / accents): Galmuri first.
const UI_DISPLAY_FONT_STACK = "'PtGalmuri', 'PtPixel', system-ui, -apple-system, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif";
// Platinum frame tones (canvas twins of the shell CSS tokens).
const PT_FRAME = '#2b3040';
const PT_FRAME2 = '#8d9bbf';
const PT_PAPER = '#f6f8fc';
const PT_PAPER2 = '#dfe6f2';
const PT_RIVET = '#6d7ba3';

class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.dpr = 1;
    this.scaleX = 1; this.scaleY = 1; // backing-store px per logical px
    this.viewW = 0; this.viewH = 0;   // logical px
    this.camX = 0; this.camY = 0;     // camera top-left in world px
    this.shakeX = 0; this.shakeY = 0; // screen-shake offset (px, logical)
    this.flashA = 0;                  // white flash overlay alpha
    this.fadeA = 0; this.fadeColor = '#000';
    this.autoTier();
  }

  autoTier() {
    let dpr = 1;
    try {
      const w = typeof window !== 'undefined' ? window : {};
      dpr = Math.min(2, w.devicePixelRatio || 1);
      const mem = (typeof navigator !== 'undefined' && navigator.deviceMemory) || 4;
      if (mem <= 2) dpr = 1; // ADR-007: auto-tier to 1 on <=2GB RAM
    } catch (e) { dpr = 1; }
    this.dpr = dpr;
  }

  // Logical viewport (game px). Internal res capped by design (gameux §2).
  // Crisp-text fix: the backing store must match the on-screen CSS size
  // (cssW x cssH) times DPR — NOT logical x DPR. Scaling the backing store
  // from the logical size made the browser upscale the finished bitmap to
  // the (much larger) CSS box, smearing all canvas text. The world
  // transform therefore becomes backing/logical (scaleX/scaleY), so
  // drawing still happens in logical units at full display resolution.
  resize(logicalW, logicalH, cssW, cssH) {
    this.viewW = logicalW; this.viewH = logicalH;
    const bw = Math.round((cssW != null ? cssW : logicalW) * this.dpr);
    const bh = Math.round((cssH != null ? cssH : logicalH) * this.dpr);
    this.canvas.width = bw;
    this.canvas.height = bh;
    this.scaleX = logicalW ? bw / logicalW : this.dpr;
    this.scaleY = logicalH ? bh / logicalH : this.dpr;
    if (this.canvas.style) {
      this.canvas.style.width = (cssW != null ? cssW : logicalW) + 'px';
      this.canvas.style.height = (cssH != null ? cssH : logicalH) + 'px';
    }
  }

  begin() {
    const c = this.ctx;
    c.setTransform(this.scaleX, 0, 0, this.scaleY, 0, 0);
    c.imageSmoothingEnabled = false;
    c.fillStyle = '#000';
    c.fillRect(0, 0, this.viewW, this.viewH);
    c.save();
    c.translate(-Math.round(this.camX) + this.shakeX, -Math.round(this.camY) + this.shakeY);
  }

  end() {
    const c = this.ctx;
    c.restore();
    if (this.flashA > 0) {
      c.fillStyle = 'rgba(255,255,255,' + this.flashA.toFixed(3) + ')';
      c.fillRect(0, 0, this.viewW, this.viewH);
    }
    if (this.fadeA > 0) {
      c.globalAlpha = Math.min(1, this.fadeA);
      c.fillStyle = this.fadeColor;
      c.fillRect(0, 0, this.viewW, this.viewH);
      c.globalAlpha = 1;
    }
  }

  // Camera centers on a world point, clamped to map bounds.
  centerOn(wx, wy, mapWpx, mapHpx) {
    this.camX = Math.max(0, Math.min(mapWpx - this.viewW, wx - this.viewW / 2));
    this.camY = Math.max(0, Math.min(mapHpx - this.viewH, wy - this.viewH / 2));
    if (mapWpx <= this.viewW) this.camX = (mapWpx - this.viewW) / 2;
    if (mapHpx <= this.viewH) this.camY = (mapHpx - this.viewH) / 2;
  }

  // Viewport rect in world px — for culling.
  viewRect() {
    return {
      x0: this.camX - TILE, y0: this.camY - TILE,
      x1: this.camX + this.viewW + TILE, y1: this.camY + this.viewH + TILE,
    };
  }

  // Blit a pre-rendered offscreen sprite (zero per-frame allocation).
  blit(sprite, dx, dy) {
    const c = this.ctx;
    const w = sprite.width, h = sprite.height;
    // Cull against viewport
    if (dx + w < this.camX - TILE || dy + h < this.camY - TILE ||
        dx > this.camX + this.viewW + TILE || dy > this.camY + this.viewH + TILE) return;
    c.drawImage(sprite, Math.round(dx), Math.round(dy));
  }

  // Bottom-anchored character blit (Wave 0 size standard): characters
  // are authored 16 wide (16x32 at the new standard, 16x16 legacy) on a
  // 1-tile footprint. The sprite is scaled to footprint width (TILE) with
  // its authored aspect ratio, and drawn so its BOTTOM sits exactly at
  // bottomY — taller art overhangs upward, never into the tile below.
  // For a legacy 16x16 sprite this draws at (dx, bottomY - 16) at native
  // size: pixel-identical to the old unscaled blit at that position.
  // Wave 3a: every character also gets the shared soft ground shadow
  // (below) at its feet line — groundY when the caller knows the true
  // ground line differs from the sprite's bottom (the follower's hop
  // lift), else bottomY itself.
  blitCharacter(sprite, dx, bottomY, groundY) {
    if (!sprite || !sprite.width || !sprite.height) return;
    const w = TILE;
    const h = Math.round(TILE * sprite.height / sprite.width);
    // Premium+ W5 (LD-1): the ground shadow SCALES with airborne height
    // — the higher the sprite's bottom floats above its ground line,
    // the smaller/fainter its shadow (hop apex ~64% of grounded area).
    const gy = groundY == null ? bottomY : groundY;
    const lift = Math.max(0, gy - bottomY);
    const s = Math.max(0.5, 1 - lift * 0.12);
    this.characterShadow(dx + w / 2, gy, s);
    this.blitS(sprite, dx, bottomY - h, w, h);
  }

  // Soft ground shadow (Wave 3a, census s3 character row): a stepped
  // pixel ellipse in two alpha passes — outer band fainter, core
  // darker — drawn rect-only like ptDisc (no arc/ellipse calls, so the
  // headless recording ctx renders it identically). Centered on the
  // footprint, sitting on the feet line: subtle and consistent for
  // every overworld character (player, follower, NPCs).
  characterShadow(cx, groundY, s) {
    const k = s == null ? 1 : s; // W5 LD-1: airborne scale (1 = grounded)
    const c = this.ctx;
    const w1 = Math.max(4, Math.round(10 * k)), w2 = Math.max(6, Math.round(14 * k)), w3 = Math.max(3, Math.round(8 * k));
    c.fillStyle = 'rgba(16,22,14,' + (0.16 * k).toFixed(3) + ')';
    c.fillRect(Math.round(cx - w1 / 2), Math.round(groundY - 3), w1, 1);
    c.fillRect(Math.round(cx - w2 / 2), Math.round(groundY - 2), w2, 2);
    c.fillRect(Math.round(cx - w1 / 2), Math.round(groundY), w1, 1);
    c.fillStyle = 'rgba(16,22,14,' + (0.20 * k).toFixed(3) + ')';
    c.fillRect(Math.round(cx - w3 / 2), Math.round(groundY - 2), w3, 2);
  }

  // Scaled blit for authored battlers (32px art -> 48px draw size).
  // imageSmoothingEnabled=false is set in begin(): crisp pixel scaling.
  blitS(sprite, dx, dy, w, h) {
    const c = this.ctx;
    if (dx + w < this.camX - TILE || dy + h < this.camY - TILE ||
        dx > this.camX + this.viewW + TILE || dy > this.camY + this.viewH + TILE) return;
    c.drawImage(sprite, Math.round(dx), Math.round(dy), Math.round(w), Math.round(h));
  }

  text(str, x, y, opts) {
    const o = opts || {};
    const c = this.ctx;
    c.font = (o.bold ? '700 ' : '400 ') + (o.size || 8) + 'px ' + (o.display ? UI_DISPLAY_FONT_STACK : UI_FONT_STACK);
    c.textBaseline = 'top';
    if (o.align) c.textAlign = o.align;
    if (o.shadow !== false) {
      c.fillStyle = o.shadowColor || 'rgba(0,0,0,0.55)';
      c.fillText(str, x + 1, y + 1);
    }
    c.fillStyle = o.color || '#fff';
    c.fillText(str, x, y);
    if (o.align) c.textAlign = 'left';
  }

  // UI v2.3 (defect 1): word-wrap measured with the EXACT font string text()
  // renders with (same stack, size, weight) — breaks fall only on spaces,
  // so no line ever ends mid-word. A single word longer than maxW is the
  // one unavoidable exception: it is hard-split so the text still fits.
  // Returns an array of line strings (at most maxLines when given).
  wrapText(str, size, maxW, opts) {
    const o = opts || {};
    const c = this.ctx;
    c.font = (o.bold ? '700 ' : '400 ') + (size || 8) + 'px ' + (o.display ? UI_DISPLAY_FONT_STACK : UI_FONT_STACK);
    const words = String(str == null ? '' : str).split(/\s+/).filter(Boolean);
    const lines = [];
    let line = '';
    const fits = (s) => c.measureText(s).width <= maxW;
    for (const word of words) {
      const trial = line ? line + ' ' + word : word;
      if (fits(trial)) { line = trial; continue; }
      if (line) { lines.push(line); line = ''; }
      if (fits(word)) { line = word; continue; }
      // Over-long single word: hard-split by characters (only case where a
      // break can fall inside a word — the word alone exceeds the line).
      let rest = word;
      while (rest && !fits(rest)) {
        let n = rest.length;
        while (n > 1 && !fits(rest.slice(0, n))) n--;
        lines.push(rest.slice(0, n));
        rest = rest.slice(n);
      }
      line = rest;
    }
    if (line) lines.push(line);
    const maxLines = o.maxLines || 0;
    return maxLines > 0 ? lines.slice(0, maxLines) : lines;
  }

  panel(x, y, w, h, fill, border) {
    // UI v2: every canvas panel is a Platinum window (see ptFrame). The
    // legacy (fill, border) signature is preserved for all callers; the
    // border argument is accepted for compatibility — the frame tones are
    // the Platinum standard on every surface.
    this.ptFrame(x, y, w, h, fill);
  }

  // Platinum window frame, rect-only (fillRect/strokeRect — the QA recording
  // ctx implements nothing else): interior fill, navy outer line, white
  // hairline, silver-blue inner line, corner rivets. `fill` may be any CSS
  // color (dark interiors keep light text readable — frame tones hold).
  ptFrame(x, y, w, h, fill) {
    const c = this.ctx;
    c.fillStyle = fill || PT_PAPER;
    c.fillRect(x, y, w, h);
    c.strokeStyle = PT_FRAME;
    c.lineWidth = 2;
    c.strokeRect(x + 1, y + 1, w - 2, h - 2);
    c.strokeStyle = '#ffffff';
    c.lineWidth = 1;
    c.strokeRect(x + 3.5, y + 3.5, w - 7, h - 7);
    c.strokeStyle = PT_FRAME2;
    c.strokeRect(x + 5.5, y + 5.5, w - 11, h - 11);
    c.fillStyle = PT_RIVET;
    const rx = [x + 8, x + w - 10], ry = [y + 8, y + h - 10];
    for (const px of rx) for (const py of ry) c.fillRect(px, py, 2, 2);
  }

  // Platinum databox (battle HP plate): stepped two-tone interior (light
  // top, cooler bottom — DS shading without gradient APIs), navy frame,
  // and the tag tail stepping toward the battler (bottom-left for the foe,
  // bottom-right for the ally). Rect-only, like ptFrame.
  ptPlate(x, y, w, h, isAlly) {
    const c = this.ctx;
    // drop shade (offset silhouette rect, not a shadow API)
    c.fillStyle = 'rgba(10,14,28,0.30)';
    c.fillRect(x + 2, y + 3, w, h);
    c.fillStyle = PT_PAPER;
    c.fillRect(x, y, w, h);
    c.fillStyle = PT_PAPER2;
    c.fillRect(x + 2, y + Math.floor(h / 2), w - 4, h - Math.floor(h / 2) - 2);
    c.strokeStyle = PT_FRAME;
    c.lineWidth = 2;
    c.strokeRect(x + 1, y + 1, w - 2, h - 2);
    c.strokeStyle = PT_FRAME2;
    c.lineWidth = 1;
    c.strokeRect(x + 3.5, y + 3.5, w - 7, h - 7);
    // tag tail: two steps descending toward the battler
    const tx = isAlly ? x + w - 14 : x + 4;
    c.fillStyle = PT_PAPER2;
    c.fillRect(tx, y + h, 10, 3);
    c.fillRect(isAlly ? tx + 3 : tx, y + h + 3, 7, 3);
    c.fillStyle = PT_FRAME;
    c.fillRect(tx, y + h + 2, 10, 1);
  }

  // HP bar with colorblind-safe stripe overlay under 25% (gameux §7).
  // The stripes are STATIC (not motion) — they always draw; they are the
  // colorblind cue, never gated on reduced motion (Uix sign-off E6 fix).
  // UI v2: Platinum dress — navy-framed recessed track, bright DS fills,
  // 1px segment ticks like the DS bar's stepped rendering.
  hpBar(x, y, w, h, frac) {
    const c = this.ctx;
    const f = Math.max(0, Math.min(1, frac));
    c.fillStyle = '#2b3040';
    c.fillRect(x - 1, y - 1, w + 2, h + 2);
    c.fillStyle = '#484860';
    c.fillRect(x, y, w, h);
    const col = f > 0.5 ? '#48c848' : (f > 0.25 ? '#f8c830' : '#f84838');
    c.fillStyle = col;
    const fw = Math.floor((w - 2) * f);
    c.fillRect(x + 1, y + 1, fw, h - 2);
    c.fillStyle = 'rgba(43,48,64,0.35)';
    for (let sx = x + 5; sx < x + 1 + fw; sx += 4) c.fillRect(sx, y + 1, 1, h - 2);
    if (f <= 0.25 && f > 0) {
      c.fillStyle = 'rgba(255,255,255,0.5)';
      for (let sx = x + 2; sx < x + w - 2; sx += 4) {
        c.fillRect(sx, y + 1, 1, h - 2);
      }
    }
  }

  // XP bar: Platinum blue, same recessed track as the HP bar. frac eases
  // out over 600ms in battle.
  xpBar(x, y, w, h, frac) {
    const c = this.ctx;
    const f = Math.max(0, Math.min(1, frac));
    c.fillStyle = '#2b3040';
    c.fillRect(x - 1, y - 1, w + 2, h + 2);
    c.fillStyle = '#484860';
    c.fillRect(x, y, w, h);
    c.fillStyle = '#3898f8';
    c.fillRect(x + 1, y + 1, Math.floor((w - 2) * f), h - 2);
  }
}


