  mind: { sky: ['#a86a9e', '#b476aa', '#c082b6', '#cc8ec2', '#d89ace', '#e4a6da'], ground: ['#9a6a94', '#8f628a', '#846080', '#795672', '#6e4e66', '#63465c'], dark: '#4a2e44', light: '#ffd8f4', accent: '#f2a7e8', motif: 'runes', tex: 'spark' },
